<?php namespace App\Controllers; use App\Services\HtmlSanitizer; use App\Services\UploadService;
final class AdminController{
 function __construct(){if(!\user())\redirect('/admin/login');}
 function dashboard():void{$where=\user()['role']==='admin'?'1=1':'author_id='.(int)\user()['id'];$stats=\db()->query("SELECT status,COUNT(*) total FROM posts WHERE $where GROUP BY status")->fetchAll();\view('admin/dashboard',['title'=>'Dashboard','stats'=>$stats,'noindex'=>true]);}
 function posts():void{$sql='SELECT p.id,p.title,p.slug,p.status,p.updated_at,u.name author FROM posts p JOIN users u ON u.id=p.author_id'.(\user()['role']==='writer'?' WHERE p.author_id=?':'').' ORDER BY p.updated_at DESC';$q=\db()->prepare($sql);$q->execute(\user()['role']==='writer'?[\user()['id']]:[]);\view('admin/posts',['title'=>'Artikel','posts'=>$q->fetchAll(),'noindex'=>true]);}
 function form(?string $id=null):void{$post=null;if($id){$q=\db()->prepare('SELECT * FROM posts WHERE id=?');$q->execute([(int)$id]);$post=$q->fetch();if(!$post||\user()['role']==='writer'&&(int)$post['author_id']!==(int)\user()['id']){http_response_code(403);exit('Akses ditolak.');}}$cats=\db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();$tags=\db()->query('SELECT * FROM tags ORDER BY name')->fetchAll();$selected=[];if($post){$q=\db()->prepare('SELECT tag_id FROM post_tags WHERE post_id=?');$q->execute([$post['id']]);$selected=$q->fetchAll(\PDO::FETCH_COLUMN);}\view('admin/post-form',['title'=>$post?'Edit Artikel':'Artikel Baru','post'=>$post,'categories'=>$cats,'tags'=>$tags,'selected'=>$selected,'noindex'=>true]);}
 function save(?string $id=null):void{\verify_csrf();$existing=null;if($id){$q=\db()->prepare('SELECT * FROM posts WHERE id=?');$q->execute([(int)$id]);$existing=$q->fetch();if(!$existing||\user()['role']==='writer'&&(int)$existing['author_id']!==(int)\user()['id']){http_response_code(403);exit('Akses ditolak.');}}$title=trim((string)($_POST['title']??''));$slug=$existing&&!isset($_POST['change_slug'])?$existing['slug']:\slugify((string)($_POST['slug']?:$title));$status=(string)($_POST['status']??'draft');$allowed=\user()['role']==='admin'?['draft','pending','published','archived']:['draft','pending'];if(!in_array($status,$allowed,true)||$title===''||!filter_var($_POST['category_id']??null,FILTER_VALIDATE_INT)){$_SESSION['error']='Periksa data dan status artikel.';\redirect($id?'/admin/artikel/'.$id.'/edit':'/admin/artikel/baru');}$body=(new HtmlSanitizer)->clean((string)($_POST['body']??''));try{\db()->beginTransaction();if($existing){if($existing['slug']!==$slug&&$existing['status']==='published'){\db()->prepare('INSERT INTO slug_redirects(old_slug,post_id) VALUES(?,?)')->execute([$existing['slug'],$id]);}$q=\db()->prepare('UPDATE posts SET category_id=?,title=?,slug=?,excerpt=?,body=?,source_url=?,meta_title=?,meta_description=?,status=?,is_featured=?,is_editor_pick=?,published_at=IF(?="published",COALESCE(published_at,UTC_TIMESTAMP()),published_at) WHERE id=?');$q->execute([(int)$_POST['category_id'],$title,$slug,trim($_POST['excerpt']??''),$body,trim($_POST['source_url']??''),trim($_POST['meta_title']??''),trim($_POST['meta_description']??''),$status,\user()['role']==='admin'?(int)isset($_POST['is_featured']):0,\user()['role']==='admin'?(int)isset($_POST['is_editor_pick']):0,$status,$id]);}else{$q=\db()->prepare('INSERT INTO posts(author_id,category_id,title,slug,excerpt,body,source_url,meta_title,meta_description,status,is_featured,is_editor_pick,published_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,IF(?="published",UTC_TIMESTAMP(),NULL))');$q->execute([\user()['id'],(int)$_POST['category_id'],$title,$slug,trim($_POST['excerpt']??''),$body,trim($_POST['source_url']??''),trim($_POST['meta_title']??''),trim($_POST['meta_description']??''),$status,\user()['role']==='admin'?(int)isset($_POST['is_featured']):0,\user()['role']==='admin'?(int)isset($_POST['is_editor_pick']):0,$status]);$id=(string)\db()->lastInsertId();}\db()->prepare('DELETE FROM post_tags WHERE post_id=?')->execute([$id]);$ins=\db()->prepare('INSERT INTO post_tags(post_id,tag_id) VALUES(?,?)');foreach((array)($_POST['tags']??[]) as $tag)if(ctype_digit((string)$tag))$ins->execute([$id,$tag]);\db()->commit();$_SESSION['success']='Artikel disimpan.';}catch(\PDOException $e){if(\db()->inTransaction())\db()->rollBack();$_SESSION['error']=$e->getCode()==='23000'?'Slug sudah digunakan.':'Artikel gagal disimpan.';}\redirect('/admin/artikel');}
 function preview(string $id):void{$q=\db()->prepare('SELECT p.*,c.name category,c.slug category_slug,u.name author,m.filename image,m.width image_width,m.height image_height,m.caption FROM posts p JOIN categories c ON c.id=p.category_id JOIN users u ON u.id=p.author_id LEFT JOIN media m ON m.id=p.featured_media_id WHERE p.id=?');$q->execute([(int)$id]);$p=$q->fetch();if(!$p||\user()['role']==='writer'&&(int)$p['author_id']!==(int)\user()['id']){http_response_code(403);exit('Akses ditolak.');}\view('post',['title'=>'Pratinjau: '.$p['title'],'post'=>$p,'tags'=>[],'related'=>[],'noindex'=>true]);}
 function taxonomy(string $type):void{\admin_only();$table=$type==='kategori'?'categories':'tags';if($_SERVER['REQUEST_METHOD']==='POST'){\verify_csrf();$name=trim($_POST['name']??'');if($name)try{\db()->prepare("INSERT INTO $table(name,slug) VALUES(?,?)")->execute([$name,\slugify($_POST['slug']?:$name)]);}catch(\PDOException){$_SESSION['error']='Nama atau slug sudah digunakan.';}\redirect('/admin/'.$type);}\view('admin/taxonomy',['title'=>ucfirst($type),'type'=>$type,'rows'=>\db()->query("SELECT * FROM $table ORDER BY name")->fetchAll(),'noindex'=>true]);}
 function settings():void{\admin_only();if($_SERVER['REQUEST_METHOD']==='POST'){\verify_csrf();$q=\db()->prepare('INSERT INTO settings(`key`,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)');foreach(['site_name','site_description','institution_intro','contact_email','contact_phone','contact_address'] as $k)$q->execute([$k,trim($_POST[$k]??'')]);\redirect('/admin/pengaturan');}\view('admin/settings',['title'=>'Pengaturan','noindex'=>true]);}
 function media():void{\admin_only();if($_SERVER['REQUEST_METHOD']==='POST'){\verify_csrf();try{$f=(new UploadService)->store($_FILES['image']??[]);\db()->prepare('INSERT INTO media(filename,original_name,mime,size,width,height,alt_text,uploaded_by) VALUES(?,?,?,?,?,?,?,?)')->execute([$f['filename'],basename($_FILES['image']['name']),$f['mime'],$f['size'],$f['width'],$f['height'],trim($_POST['alt_text']??''),\user()['id']]);}catch(\Throwable $e){$_SESSION['error']=$e->getMessage();}\redirect('/admin/media');}\view('admin/media',['title'=>'Media','rows'=>\db()->query('SELECT * FROM media ORDER BY id DESC')->fetchAll(),'noindex'=>true]);}
 function users():void{\admin_only();if($_SERVER['REQUEST_METHOD']==='POST'){\verify_csrf();$role=in_array($_POST['role']??'', ['admin','writer'],true)?$_POST['role']:'writer';if(strlen($_POST['password']??'')<12){$_SESSION['error']='Kata sandi minimal 12 karakter.';}else try{\db()->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)')->execute([trim($_POST['name']),mb_strtolower(trim($_POST['email'])),password_hash($_POST['password'],PASSWORD_DEFAULT),$role]);}catch(\PDOException){$_SESSION['error']='Email sudah digunakan.';}\redirect('/admin/pengguna');}\view('admin/users',['title'=>'Pengguna','rows'=>\db()->query('SELECT id,name,email,role,created_at FROM users ORDER BY id')->fetchAll(),'noindex'=>true]);}
 function pages():void{\admin_only();if($_SERVER['REQUEST_METHOD']==='POST'){\verify_csrf();$slug=in_array($_POST['slug']??'', ['tentang','kontak','kebijakan-privasi'],true)?$_POST['slug']:'';if($slug){$body=(new HtmlSanitizer)->clean($_POST['body']??'');\db()->prepare("INSERT INTO pages(title,slug,body,status) VALUES(?,?,?,'published') ON DUPLICATE KEY UPDATE title=VALUES(title),body=VALUES(body),status='published'")->execute([trim($_POST['title']),$slug,$body]);}\redirect('/admin/halaman');}\view('admin/pages',['title'=>'Halaman Informasi','rows'=>\db()->query('SELECT * FROM pages ORDER BY slug')->fetchAll(),'noindex'=>true]);}
}
